# Create LaTeX tables for the corrected complex-endpoint simulation.
#
# Required input directory:
#   results/supplement
#
# Required files are generated by:
#   globally_calibrated_enrichment_bop2_complex_endpoint_type1_simulation_independent_bop2.R
#
# Output directory:
#   tables/supplement

rm(list = ls())
options(stringsAsFactors = FALSE, scipen = 999)

## -----------------------------------------------------------------------------
## 1. Paths and inputs
## -----------------------------------------------------------------------------

repo_root <- normalizePath(
  Sys.getenv("ENRICHMENT_BOP2_ROOT", unset = getwd()),
  mustWork = FALSE
)
result_dir <- file.path(repo_root, "results", "supplement")
table_dir <- file.path(repo_root, "tables", "supplement")
if (identical(Sys.getenv("BOP2_COMPLEX_QUICK"), "1")) {
  result_dir <- file.path(result_dir, "quick_test")
  table_dir <- file.path(table_dir, "quick_test")
}
dir.create(table_dir, recursive = TRUE, showWarnings = FALSE)

read_required_csv <- function(filename) {
  path <- file.path(result_dir, filename)
  if (!file.exists(path)) {
    stop(
      "Required file is missing: ", path,
      "\nRun the corrected complex-endpoint simulation first."
    )
  }
  read.csv(path, check.names = FALSE, stringsAsFactors = FALSE)
}

write_tex <- function(lines, filename) {
  path <- file.path(table_dir, filename)
  writeLines(lines, path, useBytes = TRUE)
  message("  wrote ", filename)
  invisible(path)
}

selected <- read_required_csv("complex_endpoint_selected_designs.csv")
type1 <- read_required_csv("complex_endpoint_type1_by_prevalence.csv")
proposed_boundaries <- read_required_csv("complex_endpoint_proposed_boundaries.csv")
standalone_all <- read_required_csv("complex_endpoint_standalone_allcomer_bop2.csv")
positive_library <- read_required_csv(
  "complex_endpoint_standalone_positive_bop2_library.csv"
)

endpoint_order <- c(
  "Nested efficacy",
  "Co-primary efficacy",
  "Efficacy and toxicity"
)
endpoint_id_order <- c("nested", "coprimary", "efficacy_toxicity")
proposed_method <- "Globally calibrated"
comparator_method <- "Independent conventional BOP2 components"

## -----------------------------------------------------------------------------
## 2. Formatting utilities
## -----------------------------------------------------------------------------

fmt_pct <- function(x, digits = 1L) {
  ifelse(is.na(x), "--", formatC(100 * x, format = "f", digits = digits))
}

fmt_pct_bold <- function(x, digits = 1L) {
  value <- fmt_pct(x, digits)
  ifelse(value == "--", value, paste0("\\textbf{", value, "}"))
}

fmt_num <- function(x, digits = 3L) {
  ifelse(
    is.na(x), "--",
    sub("0+$", "", sub("\\.$", "", formatC(x, format = "f", digits = digits)))
  )
}

fmt_pi <- function(x) formatC(x, format = "f", digits = 1L)

method_display <- function(x) {
  out <- x
  out[out == proposed_method] <- "Proposed"
  out[out == comparator_method] <- "Independent BOP2 components"
  out
}

make_table <- function(caption, label, column_spec, header, body,
                       notes = character(), resize = FALSE,
                       font = "\\small") {
  tabular <- c(
    paste0("\\begin{tabular}{", column_spec, "}"),
    "\\toprule",
    header,
    "\\midrule",
    body,
    "\\bottomrule",
    "\\end{tabular}"
  )
  if (resize) {
    tabular <- c("\\resizebox{\\textwidth}{!}{%", tabular, "}")
  }
  out <- c(
    "\\begin{table}[htbp]",
    "\\centering",
    paste0("\\caption{", caption, "}"),
    paste0("\\label{", label, "}"),
    font,
    tabular
  )
  if (length(notes) > 0L) {
    out <- c(
      out,
      "\\begin{minipage}{0.98\\textwidth}",
      "\\footnotesize",
      notes,
      "\\end{minipage}"
    )
  }
  c(out, "\\end{table}")
}

boundary_pair <- function(endpoint_id, b1, b2, n) {
  if (endpoint_id %in% c("nested", "coprimary")) {
    if (is.na(b1) || is.na(b2) || b1 < 0L || b2 < 0L) {
      return("--")
    }
    return(paste0("(", b1, ",", b2, ")"))
  }

  b1_label <- if (is.na(b1) || b1 < 0L) "--" else as.character(b1)
  b2_label <- if (is.na(b2) || b2 > n) "--" else as.character(b2)
  if (b1_label == "--" && b2_label == "--") return("--")
  paste0("(", b1_label, ",", b2_label, ")")
}

format_stop_rule <- function(endpoint_id, boundary1, boundary2, n) {
  if (endpoint_id == "nested") {
    if (is.na(boundary1) || is.na(boundary2) ||
        boundary1 < 0L || boundary2 < 0L) return("No stopping boundary")
    return(paste0(
      "\\# CR $\\le ", boundary1,
      "$ and \\# CR/PR $\\le ", boundary2, "$"
    ))
  }
  if (endpoint_id == "coprimary") {
    if (is.na(boundary1) || is.na(boundary2) ||
        boundary1 < 0L || boundary2 < 0L) return("No stopping boundary")
    return(paste0(
      "\\# ORR $\\le ", boundary1,
      "$ and \\# EFS6 $\\le ", boundary2, "$"
    ))
  }
  parts <- character()
  if (!is.na(boundary1) && boundary1 >= 0L) {
    parts <- c(parts, paste0("\\# responses $\\le ", boundary1, "$"))
  }
  if (!is.na(boundary2) && boundary2 <= n) {
    parts <- c(parts, paste0("\\# toxicities $\\ge ", boundary2, "$"))
  }
  if (length(parts) == 0L) return("No stopping boundary")
  paste(parts, collapse = " or ")
}

## -----------------------------------------------------------------------------
## 3. Calibration summary table
## -----------------------------------------------------------------------------

selected$Endpoint <- factor(selected$Endpoint, levels = endpoint_order)
selected <- selected[order(selected$Endpoint, selected$Method), , drop = FALSE]
selected$Endpoint <- as.character(selected$Endpoint)

selected_rows <- character()
for (endpoint in endpoint_order) {
  d <- selected[selected$Endpoint == endpoint, , drop = FALSE]
  for (j in seq_len(nrow(d))) {
    positive_spec <- if (d$Method[j] == proposed_method) {
      paste0(
        "$(", fmt_num(d$lambda_positive[j]), ",",
        fmt_num(d$gamma_positive[j]), ")$"
      )
    } else {
      "Entry-specific library"
    }
    selected_rows <- c(
      selected_rows,
      paste0(
        if (j == 1L) endpoint else "", " & ",
        method_display(d$Method[j]), " & ",
        "$(", fmt_num(d$lambda_A[j]), ",",
        fmt_num(d$gamma_A[j]), ")$ & ",
        positive_spec, " & ",
        fmt_pct(d$validation_max_PRN_any[j]), " & ",
        fmt_pct(d$validation_max_PRN_all[j]), " & ",
        fmt_pct(d$validation_max_PRN_positive[j]), " \\\\"
      )
    )
  }
  if (endpoint != tail(endpoint_order, 1L)) {
    selected_rows <- c(selected_rows, "\\addlinespace")
  }
}

selected_tex <- make_table(
  caption = paste0(
    "Selected proposed designs and independently calibrated conventional ",
    "BOP2 comparators for the complex-endpoint evaluation."
  ),
  label = "tab:complex_endpoint_selected_designs",
  column_spec = "llllrrr",
  header = paste0(
    "Endpoint & Method & All-comer $(\\lambda,\\gamma)$ & ",
    "Positive component & Max. PRN-any (\\%) & Max. PRN-all (\\%) & ",
    "Max. PRN-positive (\\%) \\\\"
  ),
  body = selected_rows,
  notes = paste0(
    "Maximum rejection probabilities are from the independent validation ",
    "simulation over the prespecified biomarker-prevalence values. The ",
    "comparator positive component is an entry-specific library rather than a ",
    "single boundary function."
  ),
  resize = TRUE
)
write_tex(selected_tex, "table_complex_endpoint_selected_designs.tex")

## -----------------------------------------------------------------------------
## 4. Proposed compact boundary table
## -----------------------------------------------------------------------------

compact_consecutive <- function(d) {
  d <- d[order(d$n), , drop = FALSE]
  if (nrow(d) == 0L) return(d)
  group <- integer(nrow(d))
  group[1L] <- 1L
  if (nrow(d) > 1L) {
    for (i in 2:nrow(d)) {
      same_b1 <- (is.na(d$boundary1[i]) && is.na(d$boundary1[i - 1L])) ||
        (!is.na(d$boundary1[i]) && !is.na(d$boundary1[i - 1L]) &&
           d$boundary1[i] == d$boundary1[i - 1L])
      same_b2 <- (is.na(d$boundary2[i]) && is.na(d$boundary2[i - 1L])) ||
        (!is.na(d$boundary2[i]) && !is.na(d$boundary2[i - 1L]) &&
           d$boundary2[i] == d$boundary2[i - 1L])
      same <- same_b1 && same_b2
      consecutive <- d$n[i] == d$n[i - 1L] + 1L
      group[i] <- group[i - 1L] + as.integer(!(same && consecutive))
    }
  }
  do.call(rbind, lapply(split(d, group), function(x) {
    data.frame(
      Endpoint = x$Endpoint[1L],
      Endpoint_ID = x$Endpoint_ID[1L],
      Population = x$Population[1L],
      n_start = min(x$n),
      n_end = max(x$n),
      boundary1 = x$boundary1[1L],
      boundary2 = x$boundary2[1L],
      stringsAsFactors = FALSE
    )
  }))
}

compact_list <- list()
out_idx <- 1L
for (endpoint in endpoint_order) {
  for (population in c("All-comer", "Biomarker-positive")) {
    d <- proposed_boundaries[
      proposed_boundaries$Endpoint == endpoint &
        proposed_boundaries$Population == population,
      , drop = FALSE
    ]
    compact_list[[out_idx]] <- compact_consecutive(d)
    out_idx <- out_idx + 1L
  }
}
compact <- do.call(rbind, compact_list)
rownames(compact) <- NULL

boundary_rows <- character()
previous_endpoint <- ""
previous_population <- ""
for (i in seq_len(nrow(compact))) {
  d <- compact[i, , drop = FALSE]
  endpoint_cell <- if (d$Endpoint != previous_endpoint) d$Endpoint else ""
  population_cell <- if (
    d$Endpoint != previous_endpoint || d$Population != previous_population
  ) d$Population else ""
  n_label <- if (d$n_start == d$n_end) {
    as.character(d$n_start)
  } else {
    paste0(d$n_start, "--", d$n_end)
  }
  boundary_rows <- c(
    boundary_rows,
    paste0(
      endpoint_cell, " & ", population_cell, " & ", n_label, " & ",
      format_stop_rule(
        d$Endpoint_ID, d$boundary1, d$boundary2, d$n_end
      ), " \\\\"
    )
  )
  if (i < nrow(compact) && compact$Endpoint[i + 1L] != d$Endpoint) {
    boundary_rows <- c(boundary_rows, "\\addlinespace")
  }
  previous_endpoint <- d$Endpoint
  previous_population <- d$Population
}

boundary_tex <- c(
  "\\begin{table}[htbp]",
  "\\centering",
  paste0(
    "\\caption{Compact stopping boundaries for the globally calibrated ",
    "design with complex categorical endpoints.}"
  ),
  "\\label{tab:complex_endpoint_boundaries_compact}",
  "\\small",
  "\\begin{tabularx}{\\textwidth}{llcX}",
  "\\toprule",
  "Endpoint & Population & Number evaluated & Stop the trial if \\\\ ",
  "\\midrule",
  boundary_rows,
  "\\bottomrule",
  "\\end{tabularx}",
  "\\begin{minipage}{0.98\\textwidth}",
  "\\footnotesize",
  paste0(
    "The all-comer boundaries apply at 20, 30, and 40 patients. ",
    "Biomarker-positive boundaries apply at the immediate assessment and at ",
    "subsequent scheduled analyses that have not already been reached. At the ",
    "final analysis, satisfying the listed rule results in no efficacy claim."
  ),
  "\\end{minipage}",
  "\\end{table}"
)
write_tex(boundary_tex, "table_complex_endpoint_boundaries_compact.tex")

## -----------------------------------------------------------------------------
## 5. Type I error table
## -----------------------------------------------------------------------------

type1$Endpoint <- factor(type1$Endpoint, levels = endpoint_order)
type1 <- type1[order(type1$Endpoint, type1$pi, type1$Method), , drop = FALSE]
type1$Endpoint <- as.character(type1$Endpoint)

type1_rows <- character()
for (endpoint in endpoint_order) {
  d_endpoint <- type1[type1$Endpoint == endpoint, , drop = FALSE]
  pi_values <- sort(unique(d_endpoint$pi))
  for (j in seq_along(pi_values)) {
    pi_value <- pi_values[j]
    proposed <- d_endpoint[
      d_endpoint$Method == proposed_method &
        abs(d_endpoint$pi - pi_value) < 1e-12,
      , drop = FALSE
    ]
    comparator <- d_endpoint[
      d_endpoint$Method == comparator_method &
        abs(d_endpoint$pi - pi_value) < 1e-12,
      , drop = FALSE
    ]
    if (nrow(proposed) != 1L || nrow(comparator) != 1L) {
      stop("Incomplete type I error rows for ", endpoint, ", pi = ", pi_value)
    }
    type1_rows <- c(
      type1_rows,
      paste0(
        if (j == 1L) endpoint else "", " & ", fmt_pi(pi_value),
        " & ", fmt_pct_bold(proposed$PRN_any),
        " & ", fmt_pct(proposed$PRN_all),
        " & ", fmt_pct(proposed$PRN_positive),
        " & ", fmt_pct_bold(comparator$PRN_any),
        " & ", fmt_pct(comparator$PRN_all),
        " & ", fmt_pct(comparator$PRN_positive), " \\\\"
      )
    )
  }
  if (endpoint != tail(endpoint_order, 1L)) {
    type1_rows <- c(type1_rows, "\\addlinespace")
  }
}

replicate_values <- unique(type1$Monte_Carlo_replicates)
replicate_note <- if (length(replicate_values) == 1L) {
  paste0(format(replicate_values, big.mark = ","),
         " independent validation replicates")
} else {
  "the independent validation replicate counts reported in the result file"
}

type1_tex <- make_table(
  caption = paste0(
    "Simulation-based global and path-specific type I error rates for ",
    "complex categorical endpoints."
  ),
  label = "tab:complex_endpoint_type1",
  column_spec = "lcrrrrrr",
  header = c(
    paste0(
      "Endpoint & $\\pi$ & \\multicolumn{3}{c}{Proposed} & ",
      "\\multicolumn{3}{c}{Independent BOP2 components} \\\\"
    ),
    paste0(
      " & & \\textbf{PRN-any} & PRN-all & PRN-positive & ",
      "\\textbf{PRN-any} & PRN-all & PRN-positive \\\\"
    )
  ),
  body = type1_rows,
  notes = paste0(
    "Values are percentages based on ", replicate_note,
    " per endpoint, method, and prevalence. The comparator consists of a ",
    "standalone all-comer BOP2 and an entry-specific positive-population BOP2 ",
    "library, calibrated independently before combination."
  ),
  resize = TRUE
)
write_tex(type1_tex, "table_complex_endpoint_type1.tex")

## -----------------------------------------------------------------------------
## 6. Standalone all-comer BOP2 calibration table
## -----------------------------------------------------------------------------

standalone_all$Endpoint <- factor(standalone_all$Endpoint, levels = endpoint_order)
standalone_all <- standalone_all[order(standalone_all$Endpoint), , drop = FALSE]
standalone_all$Endpoint <- as.character(standalone_all$Endpoint)

all_rows <- vapply(seq_len(nrow(standalone_all)), function(i) {
  d <- standalone_all[i, , drop = FALSE]
  b20 <- boundary_pair(d$Endpoint_ID, d$boundary1_20, d$boundary2_20, 20L)
  b30 <- boundary_pair(d$Endpoint_ID, d$boundary1_30, d$boundary2_30, 30L)
  b40 <- boundary_pair(d$Endpoint_ID, d$boundary1_40, d$boundary2_40, 40L)
  paste0(
    d$Endpoint, " & ",
    "$(", fmt_num(d$lambda), ",", fmt_num(d$gamma), ")$ & ",
    fmt_pct(d$standalone_type1, 2), " & ",
    fmt_pct(d$standalone_power, 2), " & ",
    b20, " & ", b30, " & ", b40, " \\\\"
  )
}, character(1L))

all_tex <- make_table(
  caption = paste0(
    "Standalone calibration of the conventional all-comer BOP2 components ",
    "for complex endpoints."
  ),
  label = "tab:complex_endpoint_standalone_allcomer_bop2",
  column_spec = "lrrrrrr",
  header = paste0(
    "Endpoint & $(\\lambda,\\gamma)$ & Type I error (\\%) & Power (\\%) & ",
    "$b_{20}$ & $b_{30}$ & $b_{40}$ \\\\"
  ),
  body = all_rows,
  notes = c(
    "Each component was calibrated under its standalone 20, 30, and 40 patient schedule. The selected rule has the estimated type I error closest to, but not above, 0.10; power resolves ties.",
    "For nested endpoints, each boundary pair is (CR, CR/PR); for co-primary endpoints it is (ORR, EFS6); for efficacy--toxicity it is (response, toxicity), with the logical rule defined in the text."
  ),
  resize = TRUE
)
write_tex(all_tex, "table_complex_endpoint_standalone_allcomer_bop2.tex")

## -----------------------------------------------------------------------------
## 7. Entry-specific positive BOP2 library tables
## -----------------------------------------------------------------------------

positive_library$Endpoint <- factor(
  positive_library$Endpoint, levels = endpoint_order
)
positive_library <- positive_library[
  order(positive_library$Endpoint, positive_library$entry_n), , drop = FALSE
]
positive_library$Endpoint <- as.character(positive_library$Endpoint)

positive_table_files <- character()
for (k in seq_along(endpoint_order)) {
  endpoint <- endpoint_order[k]
  endpoint_id <- endpoint_id_order[k]
  d <- positive_library[positive_library$Endpoint == endpoint, , drop = FALSE]
  if (nrow(d) == 0L) next

  rows <- vapply(seq_len(nrow(d)), function(i) {
    r <- d[i, , drop = FALSE]
    entry_pair <- boundary_pair(
      endpoint_id, r$boundary1_at_entry, r$boundary2_at_entry, r$entry_n
    )
    pair20 <- boundary_pair(endpoint_id, r$boundary1_20, r$boundary2_20, 20L)
    pair30 <- boundary_pair(endpoint_id, r$boundary1_30, r$boundary2_30, 30L)
    pair40 <- boundary_pair(endpoint_id, r$boundary1_40, r$boundary2_40, 40L)
    paste0(
      r$entry_n, " & ", r$analysis_schedule, " & ",
      "$(", fmt_num(r$lambda), ",", fmt_num(r$gamma), ")$ & ",
      fmt_pct(r$standalone_type1, 2), " & ",
      fmt_pct(r$standalone_power, 2), " & ",
      entry_pair, " & ", pair20, " & ", pair30, " & ", pair40,
      " \\\\"
    )
  }, character(1L))

  filename <- paste0(
    "table_complex_endpoint_positive_bop2_library_", endpoint_id, ".tex"
  )
  tex <- make_table(
    caption = paste0(
      "Entry-specific standalone positive-population BOP2 library for ",
      endpoint, "."
    ),
    label = paste0("tab:complex_positive_bop2_library_", endpoint_id),
    column_spec = "clrrrrrrr",
    header = paste0(
      "Entry $m$ & Schedule & $(\\lambda,\\gamma)$ & Type I error (\\%) & ",
      "Power (\\%) & $b_m$ & $b_{20}$ & $b_{30}$ & $b_{40}$ \\\\"
    ),
    body = rows,
    notes = paste0(
      "For each attainable entry size $m=10,\\ldots,30$, the analysis ",
      "schedule consists of $m$, subsequent scheduled looks among 20 and 30, ",
      "and the final look at 40. A dash denotes a look not included in that ",
      "entry-specific schedule. Boundary pairs follow the endpoint-specific ",
      "ordering described in Table~\\ref{tab:complex_endpoint_standalone_allcomer_bop2}."
    ),
    resize = TRUE,
    font = "\\scriptsize"
  )
  write_tex(tex, filename)
  positive_table_files <- c(positive_table_files, filename)
}

## -----------------------------------------------------------------------------
## 8. Input lists and manifest
## -----------------------------------------------------------------------------

supplemental_files <- c(
  "table_complex_endpoint_selected_designs.tex",
  "table_complex_endpoint_boundaries_compact.tex",
  "table_complex_endpoint_type1.tex",
  "table_complex_endpoint_standalone_allcomer_bop2.tex",
  positive_table_files
)

write_tex(
  c(
    "% Corrected complex-endpoint tables for the Supplementary Material.",
    paste0("\\input{", supplemental_files, "}")
  ),
  "supplemental_complex_endpoint_tables_input.tex"
)

manifest <- c(
  "Corrected complex-endpoint TeX tables",
  "=====================================",
  "",
  "Required result files:",
  "  - complex_endpoint_selected_designs.csv",
  "  - complex_endpoint_type1_by_prevalence.csv",
  "  - complex_endpoint_proposed_boundaries.csv",
  "  - complex_endpoint_standalone_allcomer_bop2.csv",
  "  - complex_endpoint_standalone_positive_bop2_library.csv",
  "",
  "Generated TeX files:",
  paste0("  - ", supplemental_files),
  "",
  "Required LaTeX packages: booktabs, graphicx, tabularx."
)
writeLines(manifest, file.path(table_dir, "complex_endpoint_tables_manifest.txt"))

message("Completed. Corrected complex-endpoint tables are in: ", table_dir)
